/**
 * Types of the test-script lane of a Request (docs/integrate/TDD-REQ-TESTSCRIPT-001).
 *
 * Test scripts are generated by the Test Script Agent from the TCIR of the Request's test specs, in a git worktree of their own,
 * once execution may start; they never change the Request status and are not run here (runtime is a later step).
 *
 * @module shared/request-testscript-types
 */

export type TestScriptStatus =
  | 'pending'
  | 'running'
  | 'completed'
  | 'needs_review'
  | 'blocked'
  | 'failed'
  | 'skipped'
  | 'cancelled'
  | 'unknown'

export type TestScriptFile = {
  path: string
  /** generated, needs-review or failed (the agent's own words). */
  status: string
  attempts: number
  cases: string[]
  errors: number
}

export type TestScriptSummary = {
  counts: { files: number; generated: number; needsReview: number; failed: number; skipped: number }
  files: TestScriptFile[]
  report: string
  manifest: string
  generator: string
  costUsd: number
  seconds: number
}

export type TestScriptRun = {
  id: string
  attempt: number
  status: TestScriptStatus
  reasonCode?: string
  reasonMessage?: string
  feature?: string
  specVersion: number
  tsaJobId?: string
  branch?: string
  baseRef?: string
  worktreePath?: string
  commitSha?: string
  summary: TestScriptSummary
  startedAt?: string
  finishedAt?: string
  updatedAt?: string
}

export type TestScripts = {
  requestId: string
  /** False when the deployment does not generate test scripts: the panel shows nothing. */
  enabled: boolean
  current: TestScriptRun | null
  history: TestScriptRun[]
}

export type TestScriptReportPage = {
  path: string
  length: number
  text: string
  hasNext: boolean
  next: number
}

/** One page of an output file of the job (a generated script, the manifest, the report). */
export type TestScriptFilePage = TestScriptReportPage

/** One expected result of the spec and the assertion that checks it (assertion-manifest.json). */
export type TestScriptManifestRow = {
  /** <TC>.E<n> */
  exp: string
  case: string
  kind: string
  op: string
  value: string
  /** ok, missing, mismatch, or gap (the spec leaves the value open; `reason` says why) */
  status: string
  reason?: string
  file?: string
  line?: number
  fn?: string
  assertion?: string
}

export type TestScriptManifest = {
  feature: string
  specVersion: number
  branch: string
  rows: TestScriptManifestRow[]
}
